using System.Collections.Generic;
using System.Text;

namespace ContactConversionWizard.Core.Export
{
    /// <summary>An additional file created by an export, e.g. a contact picture.</summary>
    public sealed class ExportedFile
    {
        public ExportedFile(string fileName, byte[] content)
        {
            FileName = fileName;
            Content = content;
        }

        public string FileName { get; }

        public byte[] Content { get; }
    }

    /// <summary>The file content generated by an exporter.</summary>
    public sealed class ExportResult
    {
        public ExportResult(string content, Encoding encoding, int entryCount)
        {
            Content = content;
            Encoding = encoding;
            EntryCount = entryCount;
        }

        public string Content { get; }

        public Encoding Encoding { get; }

        /// <summary>The number of entries (contacts or lines) written.</summary>
        public int EntryCount { get; }

        /// <summary>Problems like dropped duplicates.</summary>
        public List<string> Warnings { get; } = new List<string>();

        /// <summary>Hints to show to the user after a successful export.</summary>
        public List<string> Notices { get; } = new List<string>();

        /// <summary>Files that belong to the export, such as pictures.</summary>
        public List<ExportedFile> AdditionalFiles { get; } = new List<ExportedFile>();

        public byte[] GetBytes() => Encoding.GetBytes(Content);
    }
}
